import QtQuick
import Quickshell
import Quickshell.Io
import QtQuick.Shapes
import QtQuick.Controls
import QtQuick.Layouts
import Quickshell.Wayland
import Quickshell.Widgets
import Quickshell.Hyprland 

PanelWindow {
    id: root

    // 1. UNIFICAMOS EL ESTADO EN UNA SOLA PROPIEDAD
    property bool isOpen: false

    property var themeColors: null
    property color dropColor: themeColors ? themeColors.bg : "#ff0000"

    // 2. CORREGIMOS LOS WARNINGS: Usamos implicitWidth e implicitHeight
    implicitWidth: 420
    implicitHeight: isOpen ? 200 : 1

    exclusionMode: ExclusionMode.Ignore
    color: "transparent"

    anchors {
        top: true
    }

    property int curveRadius: 20

    GlobalShortcut {
        appid: "zshell"
        name: "toggleLauncher" 
        onPressed: {
            isOpen = !isOpen
        }
    }

    // 3. RETRASO PARA EL FOCO (El truco que vimos antes)
    Timer {
        id: focusTimer
        interval: 50
        onTriggered: searchInput.forceActiveFocus()
    }

    WlrLayershell.keyboardFocus: isOpen ? WlrKeyboardFocus.Exclusive : WlrKeyboardFocus.None

    onIsOpenChanged: {
        if (isOpen) {
            searchInput.text = ""
            focusTimer.start()
        }
    }

    // 4. EL ATRACTOR DE RATÓN INVISIBLE QUE SIEMPRE ESTÁ ACTIVO
    // Ponemos esto primero para que cubra la ventana estática y active el menú
    MouseArea {
        anchors.fill: parent
        hoverEnabled: true

        // Cuando el ratón entra en la zona invisible (1px de altura), abre el menú
        onEntered: {
            if (!root.isOpen) root.isOpen = true
        }
    }

    Item {
        id: mainRect
        width: 300
        height: isOpen ? 200 : 0
        anchors.top: parent.top
        anchors.horizontalCenter: parent.horizontalCenter
        clip: false 

        Behavior on height {
            NumberAnimation {
                duration: 200 
                easing.type: Easing.OutQuad
            }  
        }

        Rectangle {
            width: parent.width
            height: parent.height + curveRadius
            y: -curveRadius 
            radius: curveRadius
            color: dropColor

            ColumnLayout {
                anchors.fill: parent
                anchors.topMargin: curveRadius + 15
                anchors.bottomMargin: 15
                anchors.leftMargin: 20
                anchors.rightMargin: 20
                spacing: 10

                opacity: isOpen ? 1 : 0
                Behavior on opacity { NumberAnimation { duration: 150 } }

                TextField {
                    id: searchInput
                    Layout.fillWidth: true
                    placeholderText: "Buscar aplicación..."
                    color: "white" 
                    padding: 10
                    font.pixelSize: 17

                    // Al escribir, devolvemos la selección al primer elemento
                    onTextChanged: resultsList.currentIndex = 0

                    // Navegación
                    Keys.onUpPressed: resultsList.decrementCurrentIndex()
                    Keys.onDownPressed: resultsList.incrementCurrentIndex()

                    Keys.onReturnPressed: {
                        if (resultsList.count > 0) {
                            // Ejecutamos el que está seleccionado actualmente con las flechas
                            resultsList.model.values[resultsList.currentIndex].execute()
                            root.isOpen = false 
                            searchInput.text = "" 
                        }
                    }

                    Keys.onEscapePressed: {
                        root.isOpen = false
                        searchInput.text = ""
                    }

                    background: Rectangle {
                        color: typeof colorLoader !== "undefined" ? colorLoader : "#333333"
                        border.color: themeColors ? themeColors.c1 : "#ffffff"
                        border.width: 2
                        radius: 6
                    }


                }

                ListView {
                    id: resultsList
                    Layout.fillWidth: true
                    Layout.fillHeight: true
                    clip: true
                    spacing: 5

                    highlightFollowsCurrentItem: true
                    currentIndex: 0

                    model: ScriptModel {
                        values: {
                            let q = searchInput.text.toLowerCase()
                            return DesktopEntries.applications.values.filter(
                                app => app.name.toLowerCase().includes(q)
                            )
                        }
                    }

                    delegate: ItemDelegate {
                        id: delegateItem
                        width: ListView.view.width
                        height: 44 

                        contentItem: RowLayout {
                            spacing: 12

                            IconImage {
                                source: Quickshell.iconPath(modelData.icon) 
                                Layout.preferredWidth: 28
                                Layout.preferredHeight: 28
                            }

                            Text {
                                text: modelData.name
                                color: "white" 
                                font.pixelSize: 15
                                verticalAlignment: Text.AlignVCenter
                                Layout.fillWidth: true
                            }
                        }

                        background: Rectangle {
                            color: (delegateItem.hovered || delegateItem.ListView.isCurrentItem) ? '#33ffffff' : "transparent"
                            radius: 6
                        }

                        onClicked: {
                            modelData.execute()
                            root.isOpen = false 
                            searchInput.text = ""
                        }
                    }
                }
            }
        }
    }

    Shape {
        anchors.right: mainRect.left
        anchors.top: mainRect.top
        width: curveRadius
        height: curveRadius
        opacity: isOpen ? 1 : 0

        ShapePath {
            fillColor: dropColor
            strokeColor: "transparent"
            PathSvg { 
                path: `M 0 0 L ${curveRadius} 0 L ${curveRadius} ${curveRadius} C ${curveRadius} ${curveRadius*0.45}, ${curveRadius*0.45} 0, 0 0 Z` 
            }
        }
    }

    Shape {
        anchors.left: mainRect.right
        anchors.top: mainRect.top
        width: curveRadius
        height: curveRadius
        opacity: isOpen ? 1 : 0

        ShapePath {
            fillColor: dropColor
            strokeColor: "transparent"
            PathSvg { 
                path: `M ${curveRadius} 0 L 0 0 L 0 ${curveRadius} C 0 ${curveRadius*0.45}, ${curveRadius*0.55} 0, ${curveRadius} 0 Z` 
            }
        }
    }
}

