// Array que alimentará nuestra lista visual
    property var filteredApps: []

    // Función de filtrado
    function updateSearch(query) {
        let q = query.toLowerCase()
        let results = []
        let apps = DesktopEntries.applications

        for (let i = 0; i < apps.count; i++) {
            let app = apps.get(i)
            if (app && app.name.toLowerCase().includes(q)) {
                results.push(app)
            }
        }
        filteredApps = results
    }

    // Llenar la lista cuando arranca el componente
    Component.onCompleted: updateSearch("")

    // Autofocus: Asegurarnos de poder escribir apenas baje el menú
    onIsOpenChanged: {
        if (isOpen) {
            searchInput.forceActiveFocus()
            searchInput.text = "" // Limpia búsquedas anteriores
        }
    }

