    Component.onCompleted: {
        menuOpen = true
    }

    property int curveRadius: 20
    property color dropColor: themeColors ? themeColors.bg : "#ff0000"

    Item {
        id: mainRect
        width: 300
        height: 200 
        anchors.top: parent.top
        anchors.horizontalCenter: parent.horizontalCenter

        // 3. Quitamos el "clip: true". Ya no lo necesitamos.

        Rectangle {
            width: parent.width

