            // (por lo que queda escondido arriba del borde). 
            // Si está abierto, crece hasta 220px.
            height: menuOpen ? 200 + curveRadius : curveRadius
            y: -curveRadius 
            radius: curveRadius
            color: dropColor

            // Esta animación ahora estirará el rectángulo como si fuera goma
            Behavior on height {
                NumberAnimation {
                    duration: 500 
                    easing.type: Easing.OutBack
                }  
            }
        }
    }

    // CONECTOR IZQUIERDO
    Shape {
        anchors.right: mainRect.left
