            }
        }
    }

    // CONECTOR DERECHO
    Shape {
        anchors.left: mainRect.right
        anchors.top: mainRect.top
        width: curveRadius
        height: curveRadius

        opacity: menuOpen ? 1 : 0
        Behavior on opacity { NumberAnimation { duration: 200 } }

        ShapePath {
            fillColor: dropColor
            strokeColor: "transparent"
