import QtQuick
import QtQuick.Shapes // Necesario para dibujar las esquinas invertidas

Item {
    id: dynamicDrop
    width: 400
    height: 100
    anchors.horizontalCenter: parent.horizontalCenter

    // --- VARIABLES QUE PUEDES AJUSTAR ---
    property int curveRadius: 20 // Qué tan ancha/suave es la curva
    property color dropColor: "#ff0000" // El color de tu rectángulo

    // 1. EL RECTÁNGULO CENTRAL
    Item {
        id: mainRect
        width: 250
        height: 60
        anchors.top: parent.top
        anchors.horizontalCenter: parent.horizontalCenter
        clip: true // Vital: corta todo lo que se salga de este marco

        Rectangle {
            width: parent.width
            height: parent.height + curveRadius
            // Lo empujamos hacia arriba para que las esquinas 
            // redondeadas superiores queden ocultas (cortadas por el clip: true)
            y: -curveRadius 
            radius: curveRadius
            color: dropColor
        }
    }

    // 2. CONECTOR IZQUIERDO (La curva de la izquierda)
    Shape {
        anchors.right: mainRect.left
        anchors.top: mainRect.top
        width: curveRadius
        height: curveRadius

        ShapePath {
            fillColor: dropColor
            strokeColor: "transparent"
            // Dibuja matemáticamente la esquina cóncava izquierda
            PathSvg { 
                path: `M 0 0 L ${curveRadius} 0 L ${curveRadius} ${curveRadius} C ${curveRadius} ${curveRadius*0.45}, ${curveRadius*0.45} 0, 0 0 Z` 
            }
        }
    }

    // 3. CONECTOR DERECHO (La curva de la derecha)
    Shape {
        anchors.left: mainRect.right
        anchors.top: mainRect.top
        width: curveRadius
        height: curveRadius

        ShapePath {
            fillColor: dropColor
            strokeColor: "transparent"
            // Dibuja matemáticamente la esquina cóncava derecha
            PathSvg { 
                path: `M ${curveRadius} 0 L 0 0 L 0 ${curveRadius} C 0 ${curveRadius*0.45}, ${curveRadius*0.55} 0, ${curveRadius} 0 Z` 
            }
        }
    }
}

import QtQuick
import Quickshell

PanelWindow {
    id: root
    width: 1920 // Ajusta al ancho de tu pantalla
    implicitHeight: 40
    color: "transparent" // Fondo de ventana invisible

    anchors {
        top: true
        left: true
        right: true
    }
    exclusionMode: ExclusionMode.Ignore
    layer: Layer.Overlay

    // Contenedor principal con bordes redondeados
    Rectangle {
        id: mainContainer
        anchors.fill: parent
        color: "#1a1a1a" // Color de fondo real del launcher
        radius: 12 // Radio de redondeo (ajusta este valor)
        clip: true // Evita que el contenido se salga de los bordes

        // Rectángulo rojo original
        Rectangle {
            id: redIndicator
            width: 100
            height: parent.height // Se ajusta a la altura del contenedor principal
            color: "red"
            anchors.horizontalCenter: parent.horizontalCenter
        }
    }
}

Rectangle {
    id: mainContainer
    anchors.fill: parent // **PASO CRÍTICO 2: EL CONTENEDOR OCUPA TODA LA VENTANA**
    color: "#1a1a1a" // Establece el color de fondo real aquí
    radius: 12 // **PASO CRÍTICO 3: APLICA EL RADIO DE REDONDEO (Ajusta el valor a tu gusto)**

    // Asegúrate de que el contenido no se salga de los bordes redondeados
    clip: true 
}

